def save_settings(send, workspace_id, values, enhanced_settings=False):
    response = send(workspace_id, {"settings": values})
    if not response.get("ok"):
        raise RuntimeError("Settings save failed")
    return {"saved": True, "enhanced": enhanced_settings}

def update_settings(storage, workspace_id, request):
    storage[workspace_id] = dict(request["settings"])
    return {"ok": True}

import unittest
from client import save_settings
from provider import update_settings


class SettingsTests(unittest.TestCase):
    def test_ordinary_save(self):
        storage = {}
        result = save_settings(lambda w, r: update_settings(storage, w, r),
                               "w", {"label": "blue"})
        self.assertTrue(result["saved"])
        self.assertEqual(storage["w"], {"label": "blue"})

